package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.material3.*;import androidx.compose.runtime.*;import com.example.aymobiledigitallibrary.data.LibraryItem;import com.example.aymobiledigitallibrary.model.*;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun LocalRegionRecallScreen(items:List<LibraryItem>,onDone:(List<RecallAnswer>)->Unit){var i by remember{ mutableIntStateOf(0)};var start by remember{ mutableLongStateOf(System.currentTimeMillis())};val out=remember{ mutableStateListOf<RecallAnswer>()};val item=items[i];ScreenContainer{TaskProgressHeader("Material Review",i+1,items.size);QuestionCard{Text("Where was this material located within the screen or page?");Text(item.title);listOf("Top","Middle","Bottom").forEach{c->ChoiceButton(c,false){val correct=item.localRegion.name.lowercase().replaceFirstChar{it.uppercase()};out+=RecallAnswer(TaskType.LOCAL_REGION,item.id,correct,c,null,c==correct,System.currentTimeMillis()-start);if(i==items.lastIndex) onDone(out) else {i++;start=System.currentTimeMillis()}}}}}}
